    D2Client::_Interaction::nCurrentInteractedNpcClassId = 0;
    ::gnNpcMenuTransactionType = 0;
    ::gnNpcMenuPreviousGold = 0;
    ::gpNpcMenuBitBuffer = 0;
    ::gpNpcMenuDialogOptions = 0;
    ::gnNpcMenuCurrentNpcClassId = 0;
