// Resets the NPC menu: nMercNameId = -1, NPCMENU_Cleanup, NPCMENU_Initialize, clears gbNpcMenuRandomDialogSeed and the two flag bytes (+0x11, bUpdated) of every D2NPCSpeech entry.
void __stdcall ResetNPCSpeeches() {
    nMercNameId = -1;
    NPCMENU_Cleanup();
    NPCMENU_Initialize();
    gbNpcMenuRandomDialogSeed = 0;
    if (D2NPCSpeechCount <= 0) {
      return;
    }

    uint8_t* pbSpeechEntry = &D2NPCSpeech[0].bUpdated;
    int nSpeechCount = D2NPCSpeechCount;
    do {
      pbSpeechEntry[-1] = false;
      *pbSpeechEntry = '\0';
      pbSpeechEntry += 0x16;
      nSpeechCount--;
    } while (nSpeechCount);
}

