        pPlayer->pUnitData.pUnitDataPlayer->eQueuedSkillId = 0;
        pPlayer->pUnitData.pUnitDataPlayer->eTargetUnitType = 0;
        pPlayer->pUnitData.pUnitDataPlayer->nTargetUnitGUID = 0;
