void __fastcall NPCMENU_HandleQuestItemPacket(uint8_t bParam, int32_t nParam) {
    D2UnitStrc* pInteractedUnit;
    pInteractedUnit = 0;
    if (bParam < 6) {
      pInteractedUnit = UNIT::Player::UNITS_FindClientSideUnit(nParam, (eD2UnitType)bParam);
    }

    switch (bParam) {
      case 1:
        break;
      case 2:

      case 4:

      case 6:
        ui::UI_CloseActivePanels(1, 0);
      return;
      default:
        return;
    }

    if (pInteractedUnit) {
      pInteractedUnit->eUnitFlags |= UNITFLAG_TARGETABLE;
    }
    if (_Interaction::geNpcUiState != NPCUI_MENU) {
      if ((uint32_t)(_Interaction::geNpcUiState - NPCUI_SHOP) <= 3) {
        NPCMENU_CloseShopUI();
        Inv::INV_ResetShopState();
        NPCMENU_CloseAllDialogs();
        _Interaction::geNpcUiState = NPCUI_NONE;
        return;
      }
      if (_Interaction::geNpcUiState == NPCUI_ITEM_SERVICE) {
        ui::thunk_NPCSHOP_IsRepairTabActive();
        NPCMENU_CloseAllDialogs();
        _Interaction::geNpcUiState = NPCUI_NONE;
        return;
      }
      if (gnNpcMenuActiveMode == '\0') {
        goto close_dialogs;
      }
    }

    gnNpcMenuActiveMode = '\0';
    NPCMENU_CloseAndResetAll();
    close_dialogs:
    NPCMENU_CloseAllDialogs();
    _Interaction::geNpcUiState = NPCUI_NONE;
}

