          if (D2NPCSpeech[nSpeechLoopIdx].bUpdated == '\x01') {
            D2NPCSpeech[nSpeechLoopIdx].bUpdated = '\0';
            nGreetingMode = 2;
          }
          if (D2NPCSpeech[nSpeechLoopIdx].bGreeting != '\x01') {
            return;
          }

          D2NPCSpeech[nSpeechLoopIdx].bGreeting = '\0';
