void __stdcall NPCMENU_RefreshMenuDialog() {
    if (!gpNpcMenuMercListBox) {
      return;
    }
    if (Dialog::gpNpcMercListDialog) {
      Dialog::FreeDialogStrc(Dialog::gpNpcMercListDialog);
      if (gpNpcMenuMercListBox) {
        gpNpcMenuMercListBox->pVtable->ScalarDeletingDestructor(gpNpcMenuMercListBox, 1);
      }

      gpNpcMenuMercListBox = 0;
      Dialog::gpNpcMercListDialog = 0;
    }

    NPCMENU_OpenInteractionDialog();
}

int __fastcall NPCMENU_OnScrollComplete(void * dwParam, int32_t nParam, int32_t nScrollState) {
    int32_t nMenuIndex;
    bool bIsInteractableSideNpc;
    gnNpcMenuTradeActionGold = NPCMENU_FindNextUnhandledMessage(gnNpcMenuRepairCostGold);
    if (gnNpcMenuRepairCostGold == 0x251) {
      Sound::SOUND_PlaySound(SOUND_WEAPON_PUNCH_4, nullptr, 0, 0, 0);
    }
    if (gnNpcMenuRepairCostGold == 0x21a) {
      Sound::SOUND_PlaySound(SOUND_ITEM_WOODSHIELD, nullptr, 0, 0, 0);
    }
    if (gnNpcMenuActiveMode == '\x01') {
      D2UnitStrc* pNpcUnit;
      if (gnNpcMenuTradeActionGold != -1 && _Interaction::bInteractingWithNpc) {
        pNpcUnit = UNIT::Player::UNITS_FindClientSideUnit(_Interaction::nCurrentInteractedNpcGUID, UNIT_MONSTER);
        if (pNpcUnit) {
          gnNpcMenuScrollCompleteMode = gnNpcMenuTradeActionGold;
          if (_Interaction::bInteractingWithNpc) {
            pNpcUnit = UNIT::Player::UNITS_FindClientSideUnit(_Interaction::nCurrentInteractedNpcGUID, UNIT_MONSTER);
          } else {
            pNpcUnit = 0;
          }

          Text::TEXT_ShowNpcDialog(pNpcUnit, gnNpcMenuScrollCompleteMode, 1);
          if (gnNpcMenuScrollMessageHead < 9) {
            gaNpcMenuHandledMessageIds[gnNpcMenuScrollMessageHead] = gnNpcMenuScrollCompleteMode;
            gnNpcMenuScrollMessageHead++;
          }

          Text::TEXT_SetScrollCompleteCallback((pfnTextScrollComplete)NPCMENU_OnScrollComplete, nullptr);
          gnNpcMenuRepairCostGold = gnNpcMenuScrollCompleteMode;
          GAME::Msg::NET_D2GS_CLIENT_Send_INT_INT(0x31, _Interaction::nCurrentInteractedNpcGUID, (uint32_t)gnNpcMenuScrollCompleteMode);
          gnNpcMenuTradeActionGold = NPCMENU_FindNextUnhandledMessage(gnNpcMenuScrollCompleteMode);
          return 1;
        }
      }

      gnNpcMenuActiveMode = 0;
      Text::TEXT_SetScrollCompleteCallback(nullptr, nullptr);
      if (_Interaction::bInteractingWithNpc) {
        pNpcUnit = UNIT::Player::UNITS_FindClientSideUnit(_Interaction::nCurrentInteractedNpcGUID, UNIT_MONSTER);
      } else {
        pNpcUnit = 0;
      }

      nMenuIndex = NPCMENU_FindMenuIndexByNpcId((int32_t)pNpcUnit);
      if (!nParam || !nScrollState) {
        if (_Interaction::nCurrentInteractedNpcClassId == 0x92 || _Interaction::nCurrentInteractedNpcClassId == 0x20f || _Interaction::nCurrentInteractedNpcClassId == 0x219 || _Interaction::nCurrentInteractedNpcClassId == 0x21a || _Interaction::nCurrentInteractedNpcClassId == 0x21b || _Interaction::nCurrentInteractedNpcClassId == 0x209 || _Interaction::nCurrentInteractedNpcClassId == 0x10a || _Interaction::nCurrentInteractedNpcClassId == 0x17a || _Interaction::nCurrentInteractedNpcClassId == 0xfb || _Interaction::nCurrentInteractedNpcClassId == 0x179 || _Interaction::nCurrentInteractedNpcClassId == 0x14b || _Interaction::nCurrentInteractedNpcClassId == 0x196 || _Interaction::nCurrentInteractedNpcClassId == 0x198) {
          bIsInteractableSideNpc = true;
        } else {
          bIsInteractableSideNpc = false;
        }
        if (!bIsInteractableSideNpc && nMenuIndex >= 0) {
          pNpcUnit = GetInteractedUnit();
          if (pNpcUnit && nMenuIndex < NPC::D2NpcMenuOptionsCount && NPC::D2NpcMenuOptions[nMenuIndex].bEnabled) {
            _Interaction::geNpcUiState = NPCUI_MENU;
            pNpcUnit = GetInteractedUnit();
            if (pNpcUnit) {
              nMenuIndex = 1;
              pNpcUnit = GetInteractedUnit();
              NPCMENU_HandleMenuSelection(nMenuIndex, pNpcUnit);
              return 1;
            }

            NPCMENU_CloseAndResetAll();
            return 0;
          }
        }
      }

      _Interaction::geNpcUiState = NPCUI_NONE;
      Inv::INV_ResetHoverAndContextState();
      NPCMENU_CloseNpcInteraction(_Interaction::nCurrentInteractedNpcGUID);
      ui::SetUIFlag(UI_NPCMENU, UI_RESET, 0);
      return 0;
    }

    gnNpcMenuActiveMode = 0;
    Text::TEXT_SetScrollCompleteCallback(nullptr, dwParam);
    gnNpcMenuRepairCostGold = 0xffff;
    NPCMENU_ShowMainMenuDialog();
    return 0;
}

// "talk" (3381 TalkMenu) option callback: slot 0 of every NPC menu row that has a talk option; also used by NPCMENU_OpenInteractionDialog.
// If the player is interacting with an NPC that still exists: frees the interaction dialog, sets the NPC UI state to 1, picks the NPC's D2NPCSpeech entry (CheckSpeachVersusInteractedUnit), stores it in g_nNpcTradeMenuState and opens the talk dialog (NPCMENU_ShowTalkDialog(3381, speech index)). Returns 1.
// Otherwise closes the interaction and returns 0. Sends no packet.
int __stdcall NPCMENU_TalkOptionCallback() {
    int nNpcSpeechIdx;
    if (_Interaction::bInteractingWithNpc) {
      D2UnitStrc* pNpcUnit;
      pNpcUnit = UNIT::Player::UNITS_FindClientSideUnit(_Interaction::nCurrentInteractedNpcGUID, UNIT_MONSTER);
      if (pNpcUnit) {
        if (Dialog::gpNpcInteractionDialog) {
          Dialog::FreeDialogStrc(Dialog::gpNpcInteractionDialog);
          Dialog::gpNpcInteractionDialog = 0;
        }

        _Interaction::geNpcUiState = NPCUI_MENU;
        nNpcSpeechIdx = CheckSpeachVersusInteractedUnit();
        gpNpcCurrentSpeech = D2NPCSpeech + nNpcSpeechIdx;
        NPCMENU_ShowTalkDialog(0xd35, nNpcSpeechIdx);
        return 1;
      }
    }

    _Interaction::geNpcUiState = NPCUI_NONE;
    Inv::INV_ResetHoverAndContextState();
    NPCMENU_CloseNpcInteraction(_Interaction::nCurrentInteractedNpcGUID);
    ui::SetUIFlag(UI_NPCMENU, UI_RESET, 0);
    return 0;
}

// Akara's "Reset Stat/Skill Points" option callback (stored by NPCMENU_EnableAkaraRespecOption, row 0 slot 2). If the interacted NPC still exists: frees the NPC dialog, CheckSpeachVersusInteractedUnit, then opens the respec confirmation dialog (NPCMENU_ShowNpcActionConfirmDialog(11168), an OK/Cancel dialog builder) and returns 1.
// Otherwise closes the NPC interaction, clears UI_NPCMENU and returns 0.
int __stdcall NPCMENU_AkaraRespecOptionCallback() {
    if (_Interaction::bInteractingWithNpc) {
      D2UnitStrc* pNpcUnit;
      pNpcUnit = UNIT::Player::UNITS_FindClientSideUnit(_Interaction::nCurrentInteractedNpcGUID, UNIT_MONSTER);
      if (pNpcUnit) {
        if (Dialog::gpNpcInteractionDialog) {
          Dialog::FreeDialogStrc(Dialog::gpNpcInteractionDialog);
          Dialog::gpNpcInteractionDialog = 0;
        }

        _Interaction::geNpcUiState = NPCUI_MENU;
        CheckSpeachVersusInteractedUnit();
        NPCMENU_ShowNpcActionConfirmDialog(0x2ba0);
        return 1;
      }
    }

    _Interaction::geNpcUiState = NPCUI_NONE;
    Inv::INV_ResetHoverAndContextState();
    NPCMENU_CloseNpcInteraction(_Interaction::nCurrentInteractedNpcGUID);
    ui::SetUIFlag(UI_NPCMENU, UI_RESET, 0);
    return 0;
}

// Akara (monstats 148) menu row 0: adds option string 11168 (respec) with callback NPCMENU_AkaraRespecOptionCallback.
// NPC quest table entry 4: quest 1, state flag 0 (Den of Evil).
int __stdcall NPCMENU_EnableAkaraRespecOption() {
    NPC::D2NpcMenuOptions[0].nOptionsCount = 4;
    NPC::D2NpcMenuOptions[0].nOptionCallback[2] = NPCMENU_AkaraRespecOptionCallback;
    NPC::D2NpcMenuOptions[0].nOptionStringId[2] = 0x2ba0;
    return 1;
}

